/// <summary>
/// MET_PaymPlusJournalPostAndTransfer
/// Bug 81475: Payment Confirmation File Not Posting
/// </summary>
class METVendPaymReconciliationPost extends VendPaymReconciliationPost
{
    

}

Method.Source:
    /// <summary>
    /// Updated out of the box method to do post and transfer instead of post
    /// </summary>
    /// <param name = "_createdJournals"></param>
    public void postNewJournals(RecordSortedList _createdJournals = this.createdJournals())
    {
        Args args;
        LedgerJournalTable ledgerJournalTable;

        args = new Args();
        args.caller(this);

        if (_createdJournals.first(ledgerJournalTable))
        {
            do
            {
                setPrefix(strFmt("@SYS28641", ledgerJournalTable.JournalName, ledgerJournalTable.JournalNum));
                args.record(ledgerJournalTable);

                // Bug 81475: Payment Confirmation File Not Posting
                // Change journal posting to post and transfer so that error lines don't block the posting
                //new MenuFunction(menuitemActionStr(LedgerJourPostLJTransVendPaym), MenuItemType::Action).run(args);
                new MenuFunction(menuitemActionStr(LedgerJourPostTrLJTransVendPaym), MenuItemType::Action).run(args);
            }
            while (_createdJournals.next(ledgerJournalTable));
        }
    }

    /// <summary>
    /// Read parameters Lines Limit Before Distribution From Journal Names. Addition to CustVendPaymReconciliationPost createNewLedgerJournalTable
    /// </summary>
    /// <param name = "_ledgerJournalName">Journal Name</param>
    /// <param name = "_ledgerJournalTable">Journal Table</param>
    /// <returns>Table buffer Journal Name</returns>
    LedgerJournalTable createNewLedgerJournalTable(LedgerJournalName _ledgerJournalName = null, LedgerJournalTable _ledgerJournalTable = null)
    {
        //Call the base class CustVendPaymPost super method
        LedgerJournalTable ledgerJournalTable = super(_ledgerJournalName,_ledgerJournalTable);

        //Check if the Line Limit on the General Journal Name Parameter (Lines Limit)
        if(_ledgerJournalName.LinesLimitBeforeDistribution > 0)
        {
            ttsbegin;

            //Select the LedgerJournalTable and update the same
            ledgerJournalTable.selectForUpdate();

            //Read the Lines Limits Parameter set in the Journal Name
            ledgerJournalTable.LinesLimitBeforeDistribution = _ledgerJournalName.LinesLimitBeforeDistribution;
            ledgerJournalTable.update();
        
       
            //Insert the table buffer into the Record Insert List
            createdJournals.ins(ledgerJournalTable,true);

            ttscommit;
        }

        return ledgerJournalTable;
    }
